mapper.select:
SELECT 
  FROM reservation r
  JOIN board_game bg ON bg.board_game_id = r.board_game_id
 WHERE r.room_number = #{roomNumber}

   AND r.status = #{status}

 ORDER BY r.reserved_at DESC

mapper.update:
UPDATE reservation
   SET status = 'fulfilled',
       fulfilled_at = NOW()
 WHERE room_number   = #{roomNumber}
   AND board_game_id = #{boardGameId}
   AND status = 'waiting'
